import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
/* eslint-disable */
import { create_events } from "@/graphql/mutations.js";
import { get_location_details } from "@/mixins/GetLocations.js";
import { API, graphqlOperation } from "aws-amplify";
import { VTimePicker } from 'vuetify/labs/VTimePicker';
export default {
  components: {
    VTimePicker
  },
  props: {
    createEvent: Boolean
  },
  mixins: [get_location_details],
  data() {
    return {
      eventDescription: "",
      eventName: "",
      loaction: [],
      searchloc: "",
      loactionitems: [],
      visibilityobject: {},
      locationupdate: null,
      loading: false,
      fromMenu: false,
      fromDate: "",
      toDate: "",
      toMenu: false,
      locationSelection: null,
      virtualAddress: "",
      physicalAddress: "",
      startMenu: false,
      startTime: "",
      endTimeMenu: false,
      endTime: "",
      eventRegestrition: null,
      eventCapacity: null,
      minDate: new Date().toISOString().split("T")[0],
      datePicker: false,
      date: "",
      datePickerTo: false,
      tempDate: null,
      tempDateTo: null,
      time: null
    };
  },
  watch: {
    createEvent: {
      async handler() {
        if (this.createEvent == true) {
          await this.get_location_details();
          // await this.fetch_details();
        }
      },
      immediate: true
    }
  },
  methods: {
    saveDate() {
      if (this.tempDate) {
        this.fromDate = this.formatDate(this.tempDate); // Format and assign tempDate to billdate
      }
      this.datePicker = false; // Close the date picker
    },
    saveDateTo() {
      if (this.tempDateTo) {
        this.toDate = this.formatDate(this.tempDateTo);
      }
      this.datePickerTo = false;
    },
    formatDate(date) {
      const d = new Date(date);
      const year = d.getFullYear();
      const month = String(d.getMonth() + 1).padStart(2, '0');
      const day = String(d.getDate()).padStart(2, '0');
      return `${year}-${month}-${day}`;
    },
    fetch_details() {
      this.locationList.forEach(element => {
        this.loactionitems.push({
          title: element.location_name,
          location_id: element.location_id
        });
      });
    },
    locationCheck() {
      if (this.locationupdate == "ALL_MEMBERS") {
        this.loaction = [];
      } else {
        this.loaction = [];
        this.loactionitems = [];
        this.locationList.forEach(element => {
          this.loactionitems.push({
            title: element.location_name,
            location_id: element.location_id
          });
        });
      }
    },
    cleardata() {
      this.toDate = "";
      this.endTime = "";
    },
    cleartime() {
      this.endTime = "";
    },
    close_dialog() {
      this.$emit("clicked", 0);
      this.$refs.form.reset();
    },
    async validate_data() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        this.create_event_info();
      }
    },
    async create_event_info() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      this.visibilityobject = {
        visible_type: this.locationupdate,
        visible_locations: this.loaction
      };
      try {
        let result = await API.graphql(graphqlOperation(create_events, {
          input: {
            event_visibility: this.visibilityobject,
            user_email_id: data.user.user_email_id,
            organization_id: data.organization.organization_id,
            to_date: this.toDate,
            from_date: this.fromDate,
            event_start_time: this.startTime,
            event_end_time: this.endTime,
            event_description: this.eventDescription,
            event_name: this.eventName,
            is_physical: this.locationSelection != null && this.locationSelection == "physicalLoc" ? true : false,
            address_or_url: this.locationSelection != null && this.locationSelection == "physicalLoc" ? this.physicalAddress != "" ? this.physicalAddress : undefined : this.virtualAddress != "" ? this.virtualAddress : undefined,
            is_register: this.eventRegestrition == "enable" ? true : false,
            event_capcity: this.eventRegestrition == "enable" ? parseInt(this.eventCapacity) : 0
          }
        }));
        var response = JSON.parse(result.data.create_events);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$refs.form.reset();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    },
    is_Number(evt) {
      evt = evt ? evt : window.event;
      var charCode = evt.which ? evt.which : evt.keyCode;
      if (charCode > 31 && (charCode < 48 || charCode > 57) && charCode !== 46) {
        evt.preventDefault();
      } else {
        return true;
      }
    }
  }
};
